/**************************************************  
Interrupt Service Routine: Start Signal Occurence  
**************************************************/ 
CY_ISR(ISR_SignalStart) 
{ 
    InProgres = 1;
 	/* Initialize variables before waveform start */ 
 	MainIdx = 0; // Set pointer to the first sample 
 	/* Disable Interrupts from this source */  	
    isr_Start_Disable();
    isr_Start_1_Disable();
 	 /* Start Timers */ 
    Green_Led_Start_Write(1);
    Green_Led_Start_Board_Write(0);
    LCD_Char_1_Position(1,9);
    LCD_Char_1_PrintString("Start  ");
 	Timer_Main_Start(); 
 	Timer_Duration_Start();
} 
/**************************************************   
Interrupt Service Routine: Generate one sample and move pointer to the next one  
**************************************************/ 
CY_ISR(ISR_GenerateSample) 
{ 	 
        if (InProgres == 1)
        {
            if (Mode == 1) 
            {
                ProcessedSample = SamplesExpFadingMod1[MainIdxExpFadingMod1];
                MainIdxExpFadingMod1++;
                if (MainIdxExpFadingMod1 >= NumOfSamplesInPeriodExpFadingMod1) 
 	 	        { 
 	 	 	        MainIdxExpFadingMod1 = 399;
                }
            }
            if (Mode == 2) 
            {
                ProcessedSample = SamplesExpFadingMod2[MainIdxExpFadingMod2];
                MainIdxExpFadingMod2++;
                if (MainIdxExpFadingMod2 >= NumOfSamplesInPeriodExpFadingMod2) 
 	 	        { 
 	 	 	        MainIdxExpFadingMod2 = 1199;
                }
            }
        }
        else
        {
            ProcessedSample = Samples[MainIdx];
            MainIdx++;
            if (MainIdx == NumOfSamplesInPeriod) 
 	 	    { 
 	 	 	    MainIdx = 0; // reset of MainIdx if it reach of the last element of Samples vector 
 	 	    }
        }
            /* Write Processed Sample to DAC */ 
 	 	IDAC_1_SetValue(ProcessedSample);
        
} 
/**************************************************  
Interrupt Service Routine: Stop Samples Generation  
**************************************************/ 
CY_ISR(ISR_StopGenerate) 
{ 
 	InProgres = 0;
 	Timer_Duration_Stop();
    MainIdxExpFadingMod1 = 0;
    MainIdxExpFadingMod2 = 0;
    Green_Led_Start_Write(0);
    Green_Led_Start_Board_Write(1);
    LCD_Char_1_ClearDisplay();
 	/* Clear interrupt flag and enable interrupt from Start signal */  	
    
    isr_Start_1_Enable();
 	isr_Start_Enable(); 
    
    isr_Start_1_ClearPending();
    isr_Start_ClearPending();   
} 
CY_ISR(ISR_Mode_1)
{
    Mode = 1;
    Mode_1_LED_Write(1);
    Mode_2_LED_Write(0);
}
CY_ISR(ISR_Mode_2)
{
    Mode = 2;
    Mode_1_LED_Write(0);
    Mode_2_LED_Write(1);
}
/**************************************************  
function name: main 
**************************************************/ 
int main() 
{    	 
    CyGlobalIntEnable;  /* Uncomment this line to enable global interrupts. */ 
    LCD_Char_1_Start();
    LCD_Char_1_ClearDisplay();
 	IDAC_1_Start();  
    
    isr_NextSample_StartEx(ISR_GenerateSample);  	
    isr_StopSamples_StartEx(ISR_StopGenerate); 
 	isr_Start_StartEx(ISR_SignalStart); 	 
    isr_Start_1_StartEx(ISR_SignalStart);
    isr_Mode_1_StartEx(ISR_Mode_1);
    isr_Mode_2_StartEx(ISR_Mode_2);
 	 	     for(;;) 
    {   
       
        if (Mode == 1) 
        {
            Mode_1_LED_Write(1);
            Mode_2_LED_Write(0);
            LCD_Char_1_Position(0,0);
            LCD_Char_1_PrintString("ExpFadingProcess");
            LCD_Char_1_Position(1,0);
            LCD_Char_1_PrintString("Mod 1");
        }
        
        else 
        {
            Mode_1_LED_Write(0);
            Mode_2_LED_Write(1);
            LCD_Char_1_Position(0,0);
            LCD_Char_1_PrintString("ExpFadingProcess");
            LCD_Char_1_Position(1,0);
            LCD_Char_1_PrintString("Mod 2");
        }
    } 
}
